function(container, apiUrl, tables) {
  const reportDateInput = container.querySelector('[data-testid="report-date-input"]');
  const departmentSelect = container.querySelector('[data-testid="department-select"]');
  const reportContentTextarea = container.querySelector('[data-testid="report-content-textarea"]');
  const progressStatusSelect = container.querySelector('[data-testid="progress-status-select"]');
  const issuesTextarea = container.querySelector('[data-testid="issues-textarea"]');
  const actionPlanTextarea = container.querySelector('[data-testid="action-plan-textarea"]');
  const saveDraftButton = container.querySelector('[data-testid="save-draft-button"]');
  const submitButton = container.querySelector('[data-testid="submit-button"]');
  const viewHistoryButton = container.querySelector('[data-testid="view-history-button"]');
  const senderNameEl = container.querySelector('[data-testid="sender-name"]');
  const senderEmailEl = container.querySelector('[data-testid="sender-email"]');
  const managerEmailEl = container.querySelector('[data-testid="manager-email"]');
  const historyList = container.querySelector('#history-list');

  const submitConfirmDialog = container.querySelector('#submit-confirm-dialog');
  const confirmCancelButton = container.querySelector('#confirm-cancel-button');
  const confirmSubmitButton = container.querySelector('#confirm-submit-button');
  const confirmSenderEmail = container.querySelector('#confirm-sender-email');
  const confirmManagerEmail = container.querySelector('#confirm-manager-email');

  const submitSuccessDialog = container.querySelector('#submit-success-dialog');
  const completeButton = container.querySelector('[data-testid="complete-button"]');
  const viewHistoryFromSuccess = container.querySelector('#view-history-from-success');

  const errorDialog = container.querySelector('#error-dialog');
  const errorMessage = container.querySelector('#error-message');
  const errorCloseButton = container.querySelector('#error-close-button');

  // テーブルインデックス
  const userTableIndex = tables.findIndex(t => t.tableName === 'ユーザー');
  const departmentTableIndex = tables.findIndex(t => t.tableName === '部門');
  const reportTableIndex = tables.findIndex(t => t.tableName === '朝会報告');
  const submissionHistoryTableIndex = tables.findIndex(t => t.tableName === '報告送信履歴');
  const emailLogTableIndex = tables.findIndex(t => t.tableName === 'メール送信ログ');

  // 初期化処理
  async function init() {
    // 本日の日付をセット
    const today = new Date().toISOString().split('T')[0];
    reportDateInput.value = today;

    // 部門一覧を取得してセレクトに追加
    if (departmentTableIndex >= 0) {
      const departments = await window.aivicApi.list(departmentTableIndex);
      if (departments && departments.length > 0) {
        departments.forEach(dept => {
          const option = document.createElement('option');
          option.value = dept.id || dept.部門ID;
          option.textContent = dept.部門名 || dept.name;
          departmentSelect.appendChild(option);
        });
      }
    }

    // ユーザー情報を取得して送信者情報を表示
    if (userTableIndex >= 0) {
      const users = await window.aivicApi.list(userTableIndex);
      if (users && users.length > 0) {
        const currentUser = users[0]; // 実際にはセッション情報から取得すべき
        senderNameEl.textContent = currentUser.表示名 || currentUser.displayName || '—';
        senderEmailEl.textContent = currentUser.メールアドレス || currentUser.email || '—';

        // 部長メールアドレスを取得（同じ部門の上位ユーザーなど）
        const managerEmail = users.find(u => u.役割 === '部長' || u.role === 'manager');
        managerEmailEl.textContent = managerEmail ? (managerEmail.メールアドレス || managerEmail.email) : '—';
      }
    }

    // 送信履歴を表示
    await loadSubmissionHistory();
  }

  // 送信履歴を読み込んで表示
  async function loadSubmissionHistory() {
    if (submissionHistoryTableIndex >= 0) {
      const history = await window.aivicApi.list(submissionHistoryTableIndex);
      if (history && history.length > 0) {
        const recentHistory = history.slice(0, 5); // 最新5件
        historyList.innerHTML = recentHistory.map(item => {
          const sendDate = new Date(item.送信日時 || item.sentAt).toLocaleString('ja-JP');
          const status = item.送信ステータス || item.status;
          const statusLabel = status === '成功' || status === 'success' ? '✓ 送信済み' : '✗ 失敗';
          return `<div style="padding: 8px 0; border-bottom: 1px solid var(--border); display: flex; justify-content: space-between; align-items: center;">
            <span style="color: var(--text);">${sendDate}</span>
            <span style="color: ${status === '成功' || status === 'success' ? 'var(--primary)' : '#d32f2f'}; font-weight: 500;">${statusLabel}</span>
          </div>`;
        }).join('');
      }
    }
  }

  // 下書き保存
  saveDraftButton.addEventListener('click', async () => {
    const formData = {
      reportDate: reportDateInput.value,
      departmentId: departmentSelect.value,
      reportContent: reportContentTextarea.value,
      progressStatus: progressStatusSelect.value,
      issues: issuesTextarea.value,
      actionPlan: actionPlanTextarea.value,
      status: 'draft'
    };

    if (!formData.reportDate || !formData.departmentId || !formData.reportContent) {
      showError('報告日付、部門、報告内容は必須です');
      return;
    }

    if (reportTableIndex >= 0) {
      const saved = await window.aivicApi.save(reportTableIndex, formData);
      if (saved) {
        alert('下書きを保存しました');
      }
    }
  });

  // 送信ボタン
  submitButton.addEventListener('click', () => {
    if (!reportDateInput.value || !departmentSelect.value || !reportContentTextarea.value) {
      showError('報告日付、部門、報告内容は必須です');
      return;
    }

    const senderEmail = senderEmailEl.textContent;
    const managerEmail = managerEmailEl.textContent;

    confirmSenderEmail.textContent = senderEmail;
    confirmManagerEmail.textContent = managerEmail;

    submitConfirmDialog.style.display = 'flex';
  });

  // 送信確認キャンセル
  confirmCancelButton.addEventListener('click', () => {
    submitConfirmDialog.style.display = 'none';
  });

  // 送信確認実行
  confirmSubmitButton.addEventListener('click', async () => {
    submitConfirmDialog.style.display = 'none';

    const formData = {
      reportDate: reportDateInput.value,
      departmentId: departmentSelect.value,
      reportContent: reportContentTextarea.value,
      progressStatus: progressStatusSelect.value,
      issues: issuesTextarea.value,
      actionPlan: actionPlanTextarea.value,
      status: 'submitted'
    };

    if (reportTableIndex >= 0) {
      const saved = await window.aivicApi.save(reportTableIndex, formData);
      if (saved) {
        // 送信履歴を記録
        if (submissionHistoryTableIndex >= 0) {
          const historyData = {
            朝会報告ID: saved.id || saved.報告ID,
            ユーザーID: senderEmailEl.textContent,
            送信日時: new Date().toISOString(),
            送信ステータス: '成功'
          };
          await window.aivicApi.save(submissionHistoryTableIndex, historyData);
        }

        // 成功ダイアログを表示
        submitSuccessDialog.style.display = 'flex';

        // フォームをリセット
        reportDateInput.value = new Date().toISOString().split('T')[0];
        departmentSelect.value = '';
        reportContentTextarea.value = '';
        progressStatusSelect.value = '';
        issuesTextarea.value = '';
        actionPlanTextarea.value = '';

        // 送信履歴を更新
        await loadSubmissionHistory();
      }
    }
  });

  // 送信完了ボタン
  completeButton.addEventListener('click', () => {
    submitSuccessDialog.style.display = 'none';
    window.showScreen('scr-1785921347004'); // 日報提出状況ダッシュボード
  });

  // 送信履歴を確認ボタン
  viewHistoryButton.addEventListener('click', () => {
    window.showScreen('scr-1785921357094'); // 日報データ照会画面
  });

  viewHistoryFromSuccess.addEventListener('click', () => {
    submitSuccessDialog.style.display = 'none';
    window.showScreen('scr-1785921357094'); // 日報データ照会画面
  });

  // エラー表示
  function showError(message) {
    errorMessage.textContent = message;
    errorDialog.style.display = 'flex';
  }

  // エラーダイアログ閉じる
  errorCloseButton.addEventListener('click', () => {
    errorDialog.style.display = 'none';
  });

  // Escキーでダイアログを閉じる
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      if (submitConfirmDialog.style.display !== 'none') {
        submitConfirmDialog.style.display = 'none';
      }
      if (submitSuccessDialog.style.display !== 'none') {
        submitSuccessDialog.style.display = 'none';
      }
      if (errorDialog.style.display !== 'none') {
        errorDialog.style.display = 'none';
      }
    }
  });

  // overlay背景クリックで閉じる
  submitConfirmDialog.addEventListener('click', (e) => {
    if (e.target === submitConfirmDialog) {
      submitConfirmDialog.style.display = 'none';
    }
  });

  submitSuccessDialog.addEventListener('click', (e) => {
    if (e.target === submitSuccessDialog) {
      submitSuccessDialog.style.display = 'none';
    }
  });

  errorDialog.addEventListener('click', (e) => {
    if (e.target === errorDialog) {
      errorDialog.style.display = 'none';
    }
  });

  // 初期化実行
  init();
}

function(container, apiUrl, tables) {
  const departmentFilter = container.querySelector('[data-testid="department-filter"]');
  const submissionChart = container.querySelector('#submission-chart');
  const pendingTbody = container.querySelector('#pending-tbody');
  const pendingCount = container.querySelector('[data-testid="pending-count"]');
  const notifyButton = container.querySelector('[data-testid="notify-button"]');
  const notifyDialog = container.querySelector('#notify-dialog');
  const notifyConfirmBtn = container.querySelector('[data-testid="notify-confirm-button"]');
  const notifyCancelBtn = container.querySelector('[data-testid="notify-cancel-button"]');
  const notifyCountText = container.querySelector('[data-testid="notify-count-text"]');
  const inputReportBtn = container.querySelector('[data-testid="input-report-button"]');
  const viewHistoryBtn = container.querySelector('[data-testid="view-history-button"]');

  let allReports = [];
  let allUsers = [];
  let allDepartments = [];

  async function loadData() {
    try {
      allUsers = await window.aivicApi.list(0) || [];
      allDepartments = await window.aivicApi.list(1) || [];
      allReports = await window.aivicApi.list(2) || [];
      renderDashboard();
    } catch (e) {
      console.error('Data load error:', e);
    }
  }

  function renderDashboard() {
    const selectedDept = departmentFilter.value;
    const filteredUsers = selectedDept 
      ? allUsers.filter(u => u.部門 === selectedDept)
      : allUsers;

    renderSubmissionChart(filteredUsers);
    renderPendingList(filteredUsers);
  }

  function renderSubmissionChart(users) {
    submissionChart.innerHTML = '';

    const deptMap = {};
    users.forEach(u => {
      const dept = u.部門 || '未分類';
      if (!deptMap[dept]) deptMap[dept] = { total: 0, submitted: 0 };
      deptMap[dept].total++;
      const hasReport = allReports.some(r => r.報告者ID === u.ユーザーID);
      if (hasReport) deptMap[dept].submitted++;
    });

    Object.entries(deptMap).forEach(([dept, data]) => {
      const rate = data.total > 0 ? Math.round((data.submitted / data.total) * 100) : 0;
      const row = document.createElement('div');
      row.style.cssText = 'display: flex; align-items: center; gap: 8px; font-size: 12px;';
      row.innerHTML = `
        <div style="width: 60px; color: var(--text-muted);">${dept}</div>
        <div style="flex: 1; height: 20px; background: var(--bg-main); border-radius: 2px; overflow: hidden; position: relative;">
          <div style="height: 100%; width: ${rate}%; background: var(--primary); transition: width 0.3s;"></div>
        </div>
        <div style="width: 50px; text-align: right; color: var(--text); font-weight: 600;">${data.submitted}/${data.total}</div>
        <div style="width: 40px; text-align: right; color: var(--primary); font-weight: 600;">${rate}%</div>
      `;
      submissionChart.appendChild(row);
    });
  }

  function renderPendingList(users) {
    const pending = users.filter(u => !allReports.some(r => r.報告者ID === u.ユーザーID));
    pendingCount.textContent = pending.length;
    pendingTbody.innerHTML = '';

    pending.forEach(user => {
      const tr = document.createElement('tr');
      tr.style.cssText = 'border-bottom: 1px solid var(--border);';
      tr.innerHTML = `
        <td style="padding: 8px 0; color: var(--text);">${user.表示名}</td>
        <td style="padding: 8px 0; color: var(--text-muted);">${user.部門 || '-'}</td>
        <td style="padding: 8px 0;">
          <button class="remind-btn" data-user-id="${user.ユーザーID}" style="padding: 4px 8px; background: transparent; color: var(--primary); border: 1px solid var(--primary); border-radius: 2px; font-size: 11px; cursor: pointer; font-family: var(--font-family);">リマインド</button>
        </td>
      `;
      pendingTbody.appendChild(tr);
    });
  }

  departmentFilter.addEventListener('change', renderDashboard);

  notifyButton.addEventListener('click', () => {
    const pending = pendingTbody.querySelectorAll('tr').length;
    notifyCountText.textContent = `${pending}名のユーザーにメール通知が送信されます。`;
    notifyDialog.style.display = 'flex';
  });

  notifyCancelBtn.addEventListener('click', () => {
    notifyDialog.style.display = 'none';
  });

  notifyConfirmBtn.addEventListener('click', async () => {
    const pending = Array.from(pendingTbody.querySelectorAll('tr')).map(tr => {
      const cells = tr.querySelectorAll('td');
      return cells[0].textContent;
    });
    console.log('Sending notifications to:', pending);
    notifyDialog.style.display = 'none';
  });

  inputReportBtn.addEventListener('click', () => {
    window.showScreen("scr-1785921335709");
  });

  viewHistoryBtn.addEventListener('click', () => {
    window.showScreen("scr-1785921357094");
  });

  container.addEventListener('click', (e) => {
    if (e.target.classList.contains('remind-btn')) {
      const userId = e.target.dataset.userId;
      console.log('Remind user:', userId);
    }
  });

  // Esc キーでダイアログを閉じる
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && notifyDialog.style.display === 'flex') {
      notifyDialog.style.display = 'none';
    }
  });

  // overlay クリックで閉じる
  notifyDialog.addEventListener('click', (e) => {
    if (e.target === notifyDialog) {
      notifyDialog.style.display = 'none';
    }
  });

  loadData();
}

function(container, apiUrl, tables) {
  const reportListEl = container.querySelector('#report-list');
  const detailPanelEl = container.querySelector('#detail-panel');
  const emptyStateEl = container.querySelector('#empty-state');
  const reportCountEl = container.querySelector('[data-testid="report-count"]');
  const searchBtn = container.querySelector('[data-testid="search-button"]');
  const backBtn = container.querySelector('[data-testid="back-button"]');
  const dateFromInput = container.querySelector('[data-testid="report-date-from"]');
  const dateToInput = container.querySelector('[data-testid="report-date-to"]');
  const deptFilterSelect = container.querySelector('[data-testid="department-filter"]');
  const keywordInput = container.querySelector('[data-testid="keyword-search"]');

  const listRowTemplate = container.querySelector('#list-row-template');
  const detailTemplate = container.querySelector('#detail-template');

  let allReports = [];
  let allUsers = {};
  let allDepartments = {};
  let selectedReportId = null;

  // データ取得
  async function loadData() {
    try {
      // テーブルインデックス: 朝会報告=0, ユーザー=1, 部門=2, 報告送信履歴=3, メール送信ログ=4
      const reports = await window.aivicApi.list(0);
      const users = await window.aivicApi.list(1);
      const departments = await window.aivicApi.list(2);
      const sendHistories = await window.aivicApi.list(3);

      allReports = reports || [];
      allUsers = {};
      allDepartments = {};

      if (users) {
        users.forEach(u => {
          allUsers[u.ユーザーID] = u;
        });
      }

      if (departments) {
        departments.forEach(d => {
          allDepartments[d.部門ID] = d;
        });
      }

      // 送信履歴をマップ化（報告IDごと）
      const sendHistoryMap = {};
      if (sendHistories) {
        sendHistories.forEach(sh => {
          if (!sendHistoryMap[sh.朝会報告ID]) {
            sendHistoryMap[sh.朝会報告ID] = [];
          }
          sendHistoryMap[sh.朝会報告ID].push(sh);
        });
      }

      // 各報告に送信履歴を付与
      allReports.forEach(r => {
        r._sendHistories = sendHistoryMap[r.報告ID] || [];
      });

      renderList(allReports);
    } catch (err) {
      console.error('データ読込エラー:', err);
    }
  }

  // 一覧描画
  function renderList(reports) {
    reportListEl.innerHTML = '';
    reportCountEl.textContent = `（${reports.length}件）`;

    if (reports.length === 0) {
      reportListEl.innerHTML = '<div style="padding: 16px; text-align: center; color: var(--text-muted); font-size: 12px;">該当する日報がありません</div>';
      return;
    }

    reports.forEach(report => {
      const row = listRowTemplate.content.cloneNode(true);
      const rowEl = row.querySelector('.report-row');
      rowEl.dataset.id = report.報告ID;

      const reportDate = new Date(report.報告日);
      row.querySelector('[data-field="reportDate"]').textContent = reportDate.toLocaleDateString('ja-JP');

      const reporter = allUsers[report.報告者ID];
      row.querySelector('[data-field="reporterName"]').textContent = reporter ? reporter.表示名 : '不明';

      const dept = allDepartments[report.部門ID];
      row.querySelector('[data-field="departmentName"]').textContent = dept ? dept.部門名 : '不明';

      row.querySelector('[data-field="content"]').textContent = report.報告内容 || '';

      rowEl.addEventListener('click', () => {
        selectedReportId = report.報告ID;
        showDetail(report);
        // 選択状態の視覚的フィードバック
        container.querySelectorAll('.report-row').forEach(r => r.style.background = 'var(--bg-main)');
        rowEl.style.background = 'var(--bg-card)';
      });

      reportListEl.appendChild(row);
    });
  }

  // 詳細表示
  function showDetail(report) {
    const detail = detailTemplate.content.cloneNode(true);

    const reportDate = new Date(report.報告日);
    detail.querySelector('[data-field="reportDate"]').textContent = reportDate.toLocaleString('ja-JP');

    const reporter = allUsers[report.報告者ID];
    detail.querySelector('[data-field="reporterName"]').textContent = reporter ? reporter.表示名 : '不明';

    const dept = allDepartments[report.部門ID];
    detail.querySelector('[data-field="departmentName"]').textContent = dept ? dept.部門名 : '不明';

    detail.querySelector('[data-field="status"]').textContent = report.進捗状況 || '未設定';

    detail.querySelector('[data-field="content"]').textContent = report.報告内容 || '';
    detail.querySelector('[data-field="issues"]').textContent = report.課題 || '（なし）';
    detail.querySelector('[data-field="action"]').textContent = report.対応予定 || '（なし）';

    // 送信履歴
    const historyEl = detail.querySelector('[data-field="sendHistory"]');
    if (report._sendHistories && report._sendHistories.length > 0) {
      const historyHtml = report._sendHistories.map(sh => {
        const sendDate = new Date(sh.送信日時);
        const sender = allUsers[sh.ユーザーID];
        return `<div style="padding: 6px; background: var(--bg-main); border-radius: 3px; margin-bottom: 4px; font-size: 11px;">
          <div style="color: var(--text);">${sendDate.toLocaleString('ja-JP')}</div>
          <div style="color: var(--text-muted); margin-top: 2px;">送信者: ${sender ? sender.表示名 : '不明'}</div>
          <div style="color: var(--text-muted); margin-top: 2px;">ステータス: <span style="color: ${sh.送信ステータス === '成功' ? 'var(--primary)' : 'var(--text-muted)'}">${sh.送信ステータス}</span></div>
          ${sh.エラーメッセージ ? `<div style="color: var(--text-muted); margin-top: 2px;">エラー: ${sh.エラーメッセージ}</div>` : ''}
        </div>`;
      }).join('');
      historyEl.innerHTML = historyHtml;
    } else {
      historyEl.textContent = '（送信履歴なし）';
    }

    detailPanelEl.innerHTML = '';
    detailPanelEl.appendChild(detail);
    detailPanelEl.style.display = 'flex';
    emptyStateEl.style.display = 'none';
  }

  // 検索実行
  function performSearch() {
    const dateFrom = dateFromInput.value ? new Date(dateFromInput.value) : null;
    const dateTo = dateToInput.value ? new Date(dateToInput.value + 'T23:59:59') : null;
    const deptFilter = deptFilterSelect.value;
    const keyword = keywordInput.value.toLowerCase();

    const filtered = allReports.filter(r => {
      const reportDate = new Date(r.報告日);

      if (dateFrom && reportDate < dateFrom) return false;
      if (dateTo && reportDate > dateTo) return false;

      if (deptFilter) {
        const dept = allDepartments[r.部門ID];
        if (!dept || dept.部門名 !== deptFilter) return false;
      }

      if (keyword) {
        const content = (r.報告内容 || '').toLowerCase();
        const issues = (r.課題 || '').toLowerCase();
        if (!content.includes(keyword) && !issues.includes(keyword)) return false;
      }

      return true;
    });

    renderList(filtered);
    selectedReportId = null;
    detailPanelEl.style.display = 'none';
    emptyStateEl.style.display = 'flex';
  }

  // イベントリスナー
  searchBtn.addEventListener('click', performSearch);
  keywordInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') performSearch();
  });

  backBtn.addEventListener('click', () => {
    window.showScreen('scr-1785921347004');
  });

  // 初期ロード
  loadData();
}
